<template>
  <div class="page dashboard-page">
    <header class="page-heading"><div><h1>日志数据概览</h1><p>基于数据库中真实上传任务和解析结果汇总</p></div><el-segmented v-model="range" :options="rangeOptions" @change="load" /></header>
    <div class="summary-grid"><div v-for="(item, index) in summary" :key="item.label" class="summary-item" :style="{ '--stagger': `${index * 70}ms` }"><el-icon :class="item.tone"><component :is="item.icon" /></el-icon><div><span>{{ item.label }}</span><strong>{{ formatNumber(animatedStats[item.key]) }}</strong></div></div></div>
    <section class="panel trend"><div class="panel-heading"><div><h2>日志与异常趋势</h2><p>按解析任务创建日期统计</p></div></div><div ref="trendRef" class="chart" /><el-empty v-if="!stats.trend.length" description="暂无趋势数据" :image-size="70" /></section>
    <div class="two-columns">
      <section class="panel"><div class="panel-heading"><div><h2>异常关键字</h2><p>真实解析结果聚合</p></div></div><el-table :data="stats.top_matches"><el-table-column prop="name" label="关键字" /><el-table-column prop="count" label="次数" width="100" /><template #empty><el-empty description="暂无异常结果" :image-size="70" /></template></el-table></section>
      <section class="panel"><div class="panel-heading"><div><h2>最近任务</h2><p>最新上传记录</p></div><el-button link type="primary" @click="router.push('/tasks')">查看全部</el-button></div><el-table :data="stats.recent_tasks"><el-table-column prop="original_name" label="文件" min-width="150" /><el-table-column prop="project_name" label="项目" /><el-table-column prop="status" label="状态" /><template #empty><el-empty description="暂无任务" :image-size="70" /></template></el-table></section>
    </div>
  </div>
</template>

<script setup>
import { markRaw, nextTick, onBeforeUnmount, onMounted, ref } from 'vue'
import { useRouter } from 'vue-router'
import * as echarts from 'echarts'
import { CircleCheck, DataLine, Files, Warning } from '@element-plus/icons-vue'
import { getDashboardStats } from '@/api/task'

const router=useRouter();const range=ref('近 7 天');const rangeOptions=['近 7 天','近 30 天'];const trendRef=ref(null);let chart=null
const stats=ref({total_lines:0,error_count:0,warning_count:0,task_count:0,completed_count:0,failed_count:0,trend:[],top_matches:[],recent_tasks:[]})
const animatedStats=ref({total_lines:0,error_count:0,task_count:0,completed_count:0})
let countupFrame=0
const summary=[
  {label:'日志总行数',key:'total_lines',tone:'blue',icon:markRaw(Files)},
  {label:'错误日志',key:'error_count',tone:'red',icon:markRaw(Warning)},
  {label:'解析任务',key:'task_count',tone:'gold',icon:markRaw(DataLine)},
  {label:'已完成任务',key:'completed_count',tone:'green',icon:markRaw(CircleCheck)}
]
const formatNumber=(value)=>Number(value||0).toLocaleString()
const animateStats=()=>{cancelAnimationFrame(countupFrame);const start=performance.now();const from={...animatedStats.value};const keys=summary.map(item=>item.key);const tick=(now)=>{const progress=Math.min(1,(now-start)/720);const eased=1-Math.pow(1-progress,3);const next={...animatedStats.value};keys.forEach((key)=>{next[key]=Math.round(Number(from[key]||0)+(Number(stats.value[key]||0)-Number(from[key]||0))*eased)});animatedStats.value=next;if(progress<1)countupFrame=requestAnimationFrame(tick)};countupFrame=requestAnimationFrame(tick)}
const load=async()=>{stats.value=await getDashboardStats(range.value==='近 30 天'?30:7);animateStats();await nextTick();draw()}
const draw=()=>{if(!trendRef.value||!stats.value.trend.length)return;const isLight=document.documentElement.dataset.logTheme==='light';const palette=isLight?{text:'#55727d',line:'rgba(49,87,101,.2)',grid:'rgba(49,87,101,.12)',tip:'rgba(247,251,252,.97)',tipText:'#263d47',tipBorder:'rgba(67,98,112,.25)'}:{text:'#aeb7c3',line:'rgba(255,255,255,.16)',grid:'rgba(255,255,255,.08)',tip:'rgba(17,20,24,.94)',tipText:'#f5f7fa',tipBorder:'rgba(255,255,255,.18)'};chart?.dispose();chart=echarts.init(trendRef.value);chart.setOption({backgroundColor:'transparent',tooltip:{trigger:'axis',backgroundColor:palette.tip,borderColor:palette.tipBorder,textStyle:{color:palette.tipText}},grid:{left:20,right:20,top:20,bottom:20,containLabel:true},xAxis:{type:'category',data:stats.value.trend.map(i=>i.date),axisLabel:{color:palette.text},axisLine:{lineStyle:{color:palette.line}},axisTick:{show:false}},yAxis:{type:'value',axisLabel:{color:palette.text},splitLine:{lineStyle:{color:palette.grid}},axisLine:{show:false}},series:[{name:'日志行数',type:'line',smooth:true,data:stats.value.trend.map(i=>i.lines),symbol:'circle',symbolSize:7,lineStyle:{width:3,color:isLight?'#0787a0':'#67e8f9'},itemStyle:{color:isLight?'#0aa7c2':'#67e8f9',borderColor:'#0e7490',borderWidth:2},areaStyle:{color:'rgba(34,211,238,.12)'}},{name:'错误',type:'line',smooth:true,data:stats.value.trend.map(i=>i.errors),symbol:'circle',symbolSize:6,lineStyle:{width:2,color:isLight?'#d9435c':'#fb7185'},itemStyle:{color:isLight?'#d9435c':'#fb7185'},areaStyle:{color:'rgba(244,63,94,.08)'}}]})}
const handleThemeChange=()=>draw()
onMounted(()=>{window.addEventListener('logmaster-theme-change',handleThemeChange);load()});onBeforeUnmount(()=>{window.removeEventListener('logmaster-theme-change',handleThemeChange);chart?.dispose();cancelAnimationFrame(countupFrame)})
</script>

<style scoped>
.page{height:100%;overflow:auto;color:#1f2937}.page-heading{display:flex;align-items:flex-end;justify-content:space-between;margin-bottom:18px}.page-heading h1{margin:0;font-size:22px}.page-heading p{margin:5px 0 0;color:#7a8493;font-size:13px}.summary-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin-bottom:16px}.summary-item{display:flex;align-items:center;gap:13px;padding:16px 18px;border:1px solid #dfe3e8;border-radius:6px;background:#fff}.summary-item>.el-icon{display:grid;width:38px;height:38px;place-items:center;border-radius:5px;font-size:20px}.summary-item .blue{color:#3478dc;background:#edf4ff}.summary-item .red{color:#d95858;background:#fff0f0}.summary-item .gold{color:#c9861b;background:#fff6e7}.summary-item .green{color:#2f9275;background:#eaf8f3}.summary-item div{display:flex;flex-direction:column;gap:4px}.summary-item span{color:#7a8493;font-size:12px}.summary-item strong{font-size:21px}.panel{padding:18px;border:1px solid #dfe3e8;border-radius:6px;background:#fff}.panel-heading{display:flex;align-items:flex-start;justify-content:space-between;margin-bottom:12px}.panel-heading h2{margin:0;font-size:15px}.panel-heading p{margin:4px 0 0;color:#8a94a3;font-size:11px}.trend{min-height:300px;margin-bottom:16px}.chart{height:240px}.two-columns{display:grid;grid-template-columns:1fr 1fr;gap:16px}@media(max-width:800px){.summary-grid{grid-template-columns:repeat(2,1fr)}.two-columns{grid-template-columns:1fr}}@media(max-width:520px){.summary-grid{grid-template-columns:1fr}.page-heading{align-items:flex-start;flex-direction:column;gap:10px}}
</style>

<style scoped>
:global(.page){font-family:Inter,"PingFang SC","Microsoft YaHei",system-ui,sans-serif!important;-webkit-font-smoothing:antialiased;text-rendering:optimizeLegibility;background:radial-gradient(circle at 50% 7%,rgba(255,255,255,.1),transparent 32%),radial-gradient(circle at 50% 82%,rgba(56,189,248,.07),transparent 52%),linear-gradient(145deg,#14171b,#1b1f25 48%,#111418)!important;color:#f5f7fa!important}.page-heading,.summary-item,.panel{background:rgba(255,255,255,.085)!important;border:1px solid rgba(255,255,255,.16)!important;box-shadow:inset 0 1px 0 rgba(255,255,255,.12),0 18px 52px rgba(0,0,0,.28)!important;border-radius:14px!important}.page-heading{padding:19px 20px!important;animation:dash-rise .55s cubic-bezier(.4,0,.2,1) both}.page-heading h1,.summary-item strong,.panel-heading h2{color:#f5f7fa!important}.page-heading p,.summary-item span,.panel-heading p{color:#b7bec8!important}.page-heading :deep(.el-segmented){--el-segmented-bg-color:rgba(0,0,0,.24);--el-segmented-item-selected-bg-color:rgba(6,182,212,.28);--el-segmented-item-selected-color:#a8f3fb;--el-segmented-color:#b7bec8}.summary-grid{gap:12px!important}.summary-item{min-height:94px;padding:16px!important;animation:dash-rise .5s var(--stagger,0ms) cubic-bezier(.4,0,.2,1) both}.summary-item>.el-icon{border-radius:11px}.summary-item .blue{color:#67e8f9;background:rgba(56,189,248,.14)}.summary-item .red{color:#fb7185;background:rgba(244,63,94,.14)}.summary-item .gold{color:#fbbf24;background:rgba(245,158,11,.14)}.summary-item .green{color:#6ee7b7;background:rgba(52,211,153,.14)}.panel{padding:18px!important}.trend{min-height:300px;margin-bottom:16px}.chart{height:240px}.two-columns{gap:12px}.panel :deep(.el-table){--el-table-bg-color:transparent;--el-table-tr-bg-color:transparent;--el-table-header-bg-color:rgba(255,255,255,.07);--el-table-row-hover-bg-color:rgba(103,232,249,.12);--el-table-border-color:rgba(255,255,255,.1);--el-table-text-color:#eef2f6;--el-table-header-text-color:#b7bec8;background:transparent!important}.panel :deep(.el-table th.el-table__cell){background:rgba(255,255,255,.07)!important;color:#c4ccd6!important;border-bottom-color:rgba(255,255,255,.13)!important}.panel :deep(.el-table td.el-table__cell){background:transparent!important;border-bottom-color:rgba(255,255,255,.1)!important}.panel :deep(.el-table__row){transition:background .24s cubic-bezier(.4,0,.2,1)}.panel :deep(.el-table__row:hover td:first-child){box-shadow:inset 2px 0 #38bdf8}.panel :deep(.el-empty__description){color:#b7bec8}.panel :deep(.el-button--primary.is-link){color:#67e8f9}.panel :deep(.el-table__inner-wrapper::before){background:rgba(255,255,255,.1)}@keyframes dash-rise{from{opacity:0;transform:translateY(12px)}to{opacity:1;transform:none}}@media(prefers-reduced-motion:reduce){*,*:before,*:after{animation-duration:.01ms!important;transition-duration:.01ms!important;scroll-behavior:auto!important}}@media(max-width:520px){.page-heading{align-items:flex-start;flex-direction:column;gap:10px}.page-heading :deep(.el-segmented){width:100%}.page-heading :deep(.el-segmented__item){flex:1}}
</style>
